package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/**
 * A sheet's period: a name unique on the sheet, from and to dates inclusive. {@code closedTotal} is the
 * due-total fixed when it was closed (null while it is open), {@code personTotals} each person's due-total for
 * it fixed then, by person id (empty while it is open; a person added later has none), and {@code personCarried} each
 * person's carried figure for it fixed then the same way. A {@code soft}-closed
 * period (not {@code closed}) has its figures fixed the same way, but its claims can still change. {@code cap} is how
 * many OPEN or PENDING claims each person may have in it (null: no cap).
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried, boolean soft,
        Integer cap) {

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, null);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to, false, null, Map.of(), Map.of(), false, cap);
    }

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }

    /** Whether the date falls inside the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** The period closed at its people's figures and carried figures; its own total is the sum of their figures. */
    public Period closedAt(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
        BigDecimal total = totals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        return new Period(sheetId, name, from, to, true, total, totals, carried, false, cap);
    }

    /** The period soft-closed at its people's figures and carried figures; its own total is the sum of their figures. */
    public Period softClosedAt(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
        BigDecimal total = totals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        return new Period(sheetId, name, from, to, false, total, totals, carried, true, cap);
    }

    public Period withPersonTotals(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
        return new Period(sheetId, name, from, to, closed, closedTotal, totals, carried, soft, cap);
    }

    public Period reopened() {
        return new Period(sheetId, name, from, to, false, null, Map.of(), Map.of(), false, cap);
    }
}
package net.officefloor.hq.app.period;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A period as the screen sees it: the dates as yyyy-mm-dd, the due-total fixed when closed (null while open), and
 * each person's due-total for it fixed then, by person id (empty while open; a person added later has none), and
 * each person's carried figure for it fixed then the same way (a period fixed before carried figures were has none), and
 * whether it is soft-closed (its figures fixed so, its claims still open to change), and its claim cap (null: none).
 */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<Long, String> personTotals, Map<Long, String> personCarried, boolean soft, Integer cap) {

    public static PeriodResponse from(Period period) {
        Map<Long, String> totals = new LinkedHashMap<>();
        period.personTotals().forEach((id, total) -> totals.put(id, total.toPlainString()));
        Map<Long, String> carried = new LinkedHashMap<>();
        period.personCarried().forEach((id, figure) -> carried.put(id, figure.toPlainString()));
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(), period.closed(),
                period.closedTotal() == null ? null : period.closedTotal().toPlainString(), totals, carried, period.soft(), period.cap());
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPeriods {
    public void respond(@PathVariable("sheetId") String sheetId, Periods periods,
            ObjectResponse<List<PeriodResponse>> response) {
        response.send(periods.list(sheetId.trim()).stream().map(PeriodResponse::from).toList());
    }
}
