import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePaste {
    // Every line is checked before any is added: name,amount,date,note — the name a person's name or alias on the sheet (ignoring
    // case and surrounding spaces), the rest by the claim form's rules (a blank date is the entry date, else the sheet's today, the note
    // may hold commas or be absent). A note ending in " #<reference>" gives the claim that reference (that part is not
    // the note), refused when the sheet or an earlier line already uses it (ignoring case). Blank lines are skipped; a
    // paste with no line is refused.
    // A line whose person, date and note match one of the person's claims as they stood before the paste (VOID and DELETED
    // ones aside) updates the newest such DRAFT instead of adding a claim; matches that include no DRAFT refuse the line,
    // and so do two lines updating the same DRAFT.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteRequest body, People people,
            Claims claims, Settings settings, Holidays holidays, Periods periods, Out<PastedLines> out)
            throws InvalidClaimException, ClaimInClosedPeriodException, ClaimAfterRetirementException {
        String sheet = sheetId.trim();
        String text = body == null || body.text() == null ? "" : body.text();
        List<PastedLine> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        List<Claim> before = claims.list(sheet);
        Set<Long> drafts = new HashSet<>();
        int n = 0;
        for (String line : text.split("\\r?\\n")) {
            n++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            if (fields.length < 2) {
                throw new InvalidClaimException("Line " + n + ": type name,amount,date,note.");
            }
            String name = fields[0].trim();
            Person person = name.isEmpty() ? null : people.findByName(sheet, name);
            if (person == null) {
                throw new InvalidClaimException("Line " + n + ": no person " + name + " on this sheet.");
            }
            String note = fields.length > 3 ? fields[3].trim() : "";
            String ref = "";
            int hash = note.lastIndexOf(" #");
            if (hash >= 0) {
                ref = note.substring(hash + 2);
                note = note.substring(0, hash);
            }
            ClaimInput input;
            try {
                input = ValidateClaim.parse(new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "", note, "", ref, ""));
                if (input.ref() != null && !refs.add(input.ref().toLowerCase(Locale.ROOT))) {
                    throw new InvalidClaimException("The reference " + input.ref() + " is given twice in the paste.");
                }
                RefuseUsedRef.refuse(input.ref(), sheet, 0, claims);
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + n + ": " + e.getMessage());
            }
            LocalDate date = input.date() != null ? input.date() : settings.entryDate(sheet);
            LocalDate dueBy = holidays.dueBy(sheet, date, person.termsOn(date, settings));
            Period closed = periods.closedOn(sheet, dueBy);
            if (closed != null) {
                throw new ClaimInClosedPeriodException("Line " + n + ": the period " + closed.name()
                        + " is closed: no claim due by " + dueBy + " can be added.");
            }
            RefuseRetiredInput.check(person, date);
            Claim draft = null;
            boolean matched = false;
            for (Claim claim : before) {
                if (claim.personId() == person.id() && date.equals(claim.date())
                        && note(input.note()).equals(note(claim.note())) && claim.status() != ClaimStatus.VOID
                        && claim.status() != ClaimStatus.DELETED) {
                    matched = true;
                    if (claim.status() == ClaimStatus.DRAFT) {
                        draft = claim;
                        break;
                    }
                }
            }
            if (matched && draft == null) {
                throw new InvalidClaimException("Line " + n + ": " + person.name() + "'s claim of " + date
                        + " with that note is not a DRAFT: it cannot be pasted again.");
            }
            if (draft != null && !drafts.add(draft.id())) {
                throw new InvalidClaimException("Line " + n + ": an earlier line already updates " + person.name()
                        + "'s DRAFT claim of " + date + " with that note.");
            }
            lines.add(new PastedLine(person, input, draft));
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Paste at least one line of name,amount,date,note.");
        }
        out.set(new PastedLines(lines));
    }

    /** A note as a paste line and a claim are matched on: trimmed, none as empty. */
    private static String note(String note) {
        return note == null ? "" : note.trim();
    }
}
# POST /api/sheets/{sheetId}/claims/paste — add and open a claim per pasted line. Body {"text":"..."}, lines of
# name,amount,date,note (a blank date is the entry date, else the sheet's today; the note may hold commas or be absent, and may end in " #<reference>": that part is the claim's reference, not its note). Every line is
# checked first, by the claim form's rules and against a person of that name (ignoring case) on the sheet: 400 for a
# bad line, a name not on the sheet, a reference already used on the sheet or repeated in the paste (ignoring case), 422 for a date inside a closed period or after the person's retirement.
# A line whose person, date and note match one of the person's claims as they stood before the paste (VOID and DELETED
# ones aside) updates the newest such DRAFT instead (CLAIM_EDITED when its amount changes); 400 when the matches include
# no DRAFT, or an earlier line already updates it.
# Then, in paste order, each claim is added (or edited) and opened as its open button opens it (CLAIM_OPENED, then the
# ROLLUP and TOTALS lines), all in one transaction: any refusal the open button would give refuses the whole paste, and
# then nothing is stored or recorded. Responds {"added":n}, the lines that went through.
# The add step owns its transaction, so the pipeline is not governed.
